// Generated by `pnpm nx g @app/generators:action bundles.import`. Requests go through the real router
// with createTestEngine().inject. They fail until createBundlesImportAction is implemented; do not weaken them.
import { bundlesImport } from '@app/contracts';
import { createRoleAuthorizer } from '@app/kernel';
import {
  createBundlesImportAction,
  createConnectionsFakeDeps,
} from '@app/svc-connections';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

const subject = () =>
  createBundlesImportAction(
    createConnectionsFakeDeps({ ownerId: 'local-token' }),
  );
const def = bundlesImport;
const KEY = 'generated-spec-key-0001';
let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('POST /bundles/import', () => {
  it('GP-1 (OQ-783) the route runs bundles.import with no connection armed: it declares scope local, so the prod lock does not apply and the call answers 200', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'POST',
      path: '/bundles/import',
      payload: {
        bundle: {
          format: 'connection-bundle',
          version: 1,
          exportedAt: 1,
          secretsIncluded: false,
          profiles: [],
        },
      },
      headers: { 'idempotency-key': KEY },
    });

    // The router sends no environment class, so the call is "prod". The action declares scope 'local' (it
    // changes only the engine's own state), so the lock has nothing to arm and lets it through (OQ-783).
    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
    expect(engine.audit.attempts).toHaveLength(1);
  });

  it('GP-2 a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'POST',
      path: '/bundles/import',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-3 a caller that does not hold connection.manage gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    const answer = await engine.inject({
      method: 'POST',
      path: '/bundles/import',
      payload: {
        bundle: {
          format: 'connection-bundle',
          version: 1,
          exportedAt: 1,
          secretsIncluded: false,
          profiles: [],
        },
      },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('GP-4 input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'POST',
      path: '/bundles/import',
      payload: { unexpected: true },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-5 another method on the same path is 405', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'GET',
      path: '/bundles/import',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('POST');
  });
});
